using System.Text.Json;
using Thunderduck.Data;
using Xunit;

/// <summary>Differential test against DuckDB's own tokenizer: every case in
/// data/lexer_corpus.json (generated by data/gen_lexer_corpus.py) says whether
/// DuckDB reads the `@a` as SQL or as part of a string/comment. The renderer
/// must substitute exactly the former — any disagreement is a place where a
/// value could be spliced into a string DuckDB still considers open.</summary>
public class LexerCorpusTests
{
    [Fact]
    public void Renderer_agrees_with_duckdb_tokenizer_on_every_corpus_case()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "data", "lexer_corpus.json");
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        var mismatches = new List<string>();
        var count = 0;
        foreach (var c in doc.RootElement.GetProperty("cases").EnumerateArray())
        {
            count++;
            var sql = c.GetProperty("sql").GetString()!;
            var duckdbSaysCode = c.GetProperty("code").GetBoolean();
            var rendered = SqlParameterRenderer.Render(sql,
                new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase) { ["a"] = 424242 });
            var substituted = !rendered.Contains("@a", StringComparison.Ordinal);
            if (substituted != duckdbSaysCode)
                mismatches.Add($"{(duckdbSaysCode ? "missed" : "SPLICED")}: {JsonSerializer.Serialize(sql)}");
        }
        Assert.True(count > 1000, $"corpus too small: {count}");
        Assert.True(mismatches.Count == 0,
            $"{mismatches.Count} disagreements with DuckDB:\n" + string.Join("\n", mismatches.Take(15)));
    }
}
